import {mountCloud} from './cloud.mjs';
import {mountInstallCard} from './pwa.mjs';
import {fresh,clone,localDate,WORKOUTS,startValidation,record,undo,configure,validateBackup,markdown,weekRange} from './engine.mjs';
const KEY='mantou-training-v1';const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cloud=null;let state=fresh(),page='plan',workout=({1:'upper',2:'lower',4:'upper',5:'light'})[new Date().getDay()]||'upper',activeId=null,pendingImport=null,toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw)state=validateBackup(JSON.parse(raw));localStorage.setItem(KEY,JSON.stringify(state));}catch(e){$('storageWarning').hidden=false;$('storageWarning').textContent='设备存储不可用或已有数据无法读取。请先检查浏览器权限或恢复备份；保存失败时不会假装记录成功。';$('saveStatus').textContent='请检查设备存储';}
function transact(fn){const next=clone(state);const result=fn(next);try{if(!cloud?.save(next))localStorage.setItem(KEY,JSON.stringify(next));}catch(e){throw Error((e?.message?e.message+'：':'')+'未能写入设备存储，本次更改尚未保存。请检查浏览器存储设置，或先导出备份。');}state=next;$('saveStatus').textContent=cloud?.isAccount()?'已保存本机 · 自动同步':'已保存在此设备';return result;}
function notify(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4500);}
function attempt(fn){try{return fn()}catch(e){notify(e.message);return null;}}
const badge=e=>e.blocked?['已暂停','blocked']:e.validation?[`验证 ${e.validation.streak} / 2`,'active']:e.records.length?['已记录','']:['待首次记录',''];
const reduction=()=>!!state.temporary[localDate()+':'+workout];
function dosage(e,reduced=false){return `${e.sides?'每侧 ':''}${reduced?Math.max(1,e.sets-1):e.sets} 组 × ${e.min}–${e.max} ${e.unit}`;}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='plan')renderPlan();else if(page==='history')renderHistory();else renderExport();document.dispatchEvent(new Event('training:render'));}
function renderPlan(){const w=WORKOUTS[workout],reduced=reduction();$('main').innerHTML=`<div class="eyebrow">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</div><div class="plan-heading"><h1>今天的训练</h1><span class="muted">正课 ≤30 分钟</span></div><div class="plan-toolbar"><label class="workout-select"><span class="sr-only">切换训练类型</span><select id="workoutSelect">${Object.entries(WORKOUTS).map(([key,x])=>`<option value="${key}" ${key===workout?'selected':''}>${x.name}</option>`).join('')}</select></label><button class="inline" id="reduce">${reduced?'恢复原组数':'今天减量'}</button></div><p class="session-hint">${w.hint}</p>${reduced?'<div class="callout">仅今天、本类训练：每项减少一组，至少保留一组。原计划不变，减量记录不参与进阶验证。</div>':''}<div class="exercise-grid">${w.ids.map(id=>{const e=state.exercises[id],[label,cls]=badge(e);return `<article class="card" data-exercise="${id}"><div class="row start"><span class="name">${esc(e.name)}</span><span class="pill ${cls}">${label}</span></div><div class="dose">${reduced?Math.max(1,e.sets-1):e.sets} 组 <small>· ${e.sides?'每侧 · ':''}${(reduced?e.target.slice(0,Math.max(1,e.sets-1)):e.target).join(' / ')} ${e.unit}</small></div><div class="target" hidden>${e.blocked?'该动作已暂停，请先处理不适':`本次参考目标：${e.sides?'每侧 ':''}${(reduced?e.target.slice(0,Math.max(1,e.sets-1)):e.target).join(' / ')} ${e.unit}`}</div><p class="rest-note">休息 ${e.rest===90?'90–120':'60–90'} 秒</p><details class="exercise-help"><summary>动作要点与阻力</summary><p>${esc(e.cue)}<br>${esc(e.load)}<br>训练范围：${dosage(e,reduced)}</p></details><button class="open" data-open="${id}">${e.blocked?'查看暂停状态':'记录这一项'} <span aria-hidden="true">＋</span></button></article>`;}).join('')}</div><details><summary>每周安排</summary><p>周一、周四：上肢；周二：下肢与腹部；周五：轻下肢与核心；周三休息，周六羽毛球、周日恢复。按实际球日调整，不自动补课。</p></details><details><summary>训练边界与复盘</summary><p>正课最多30分钟；热身另计4–5分钟，包括轻活动和当天动作的轻量练习。超时先减最后辅助动作末组，不压缩必要休息。反向卷腹难控制时，先暂停该项并另行确认死虫版本。</p><p>周六羽毛球是暂定位置，按实际球日调整，重腿训练尽量不紧挨球日前一天。周五如影响球日，深蹲、臀桥先各减一组。单项临时减组可在动作里设置。</p><p>首次执行满两周校准；每四周观察体型、腰围与穿衣感受。工具判断训练进阶条件，不判断参考图完成度。明确疼痛停止相关动作；持续或加重的不适需评估。</p><p>弹力带检查破损、固定牢靠，不超过厂家拉伸范围。登录后跨设备同步；建议每周导出完整备份。</p></details><div class="screen-note">初始计划更新于 2026.10.22；首次使用不表示已经完成训练。</div>`;
$('workoutSelect').onchange=e=>{workout=e.target.value;renderPlan()};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openExercise(b.dataset.open));$('reduce').onclick=()=>attempt(()=>{transact(s=>{const k=localDate()+':'+workout;s.temporary[k]=!s.temporary[k]});renderPlan();notify(reduction()?'只调整今天，原计划保持。':'已恢复原组数。')});}
function choices(name,options){return `<div class="choices">${options.map(([value,label])=>`<label class="choice"><input type="radio" name="${name}" value="${value}" required><span>${label}</span></label>`).join('')}</div>`;}
function openExercise(id){activeId=id;const e=state.exercises[id],v=e.validation,reduced=reduction()||!!state.temporary[localDate()+':exercise:'+id];$('dialogTitle').textContent=e.name;$('dialogEyebrow').textContent=WORKOUTS[workout].name+' / 单动作调整';$('dialogContent').innerHTML=`<div class="muted">${dosage(e)} · 当前目标 ${e.target.join('/')} ${e.unit}</div>${e.blocked?`<div class="warning">该动作已暂停自动推进。明确疼痛时停止相关动作；持续或加重的不适需评估。</div><label class="check-label"><input type="checkbox" id="resumeCheck">我确认不适已处理、目前适合恢复该动作。</label><button class="btn secondary" id="resume">恢复记录，重新校准</button>`:`<div class="callout">${v?`两次验证已开启 · ${v.streak} / 2 达标。${v.streak?'下一次实际训练再记录。':'从下一条实际记录开始。'}`:'按需记录即可。想提高目标时，先开启这个动作的两次验证。'}</div>${!v?'<button class="btn secondary" id="startValidation">感觉太轻 / 开启两次进阶验证</button>':'<div class="progress-track"><i style="width:'+v.streak*50+'%"></i></div><button class="inline" id="cancelValidation">先保持，结束这轮验证</button>'}<button class="inline" id="singleReduce">${state.temporary[localDate()+':exercise:'+id]?'取消这个动作的临时减组':'只让这个动作今天少一组'}</button>`}
<form id="recordForm"><label class="field" for="trainingDate">实际训练日期</label><input class="text-input" id="trainingDate" name="date" type="date" value="${localDate()}" max="${localDate()}" required><label class="check-label"><input type="checkbox" id="temporaryRecord" ${reduced?'checked':''}>这是一次临时减量训练（少一组，不参与进阶）</label><div class="field">各组实际完成${e.unit==='秒'?'秒数':'次数'}${e.sides?' · 填写每侧较少的完成量':''}</div><div class="inputs" id="setInputs"></div><div class="field">${e.unit==='秒'?'是否还保持稳定、能再规范保持一小段？':'最后一组，还能规范做几次？'}</div>${choices('rir',e.unit==='秒'?[['steady','稳定、有余量'],['0','接近失控'],['unknown','不确定']]:[['0','0–1 次'],['2','2–3 次'],['4','约 4 次或更多'],['unknown','不确定']])}<div class="field">动作与恢复情况</div>${choices('quality',[['normal','规范、恢复正常'],['form','动作变形'],['fatigue','明显疲劳'],['pain','疼痛 / 明显不适']])}<div class="field">训练条件是否可比？</div>${choices('comparable',[['yes','一致，无中间漏记'],['no','变化 / 中间漏记'],['unknown','不确定']])}<div class="hint" style="margin-top:8px">同一版本、阻力、幅度及大致休息相同。开启验证后的首条记录，只需确认本次使用当前版本。中间练过却漏记，选“变化 / 中间漏记”。</div><div id="formError" role="alert"></div><button class="btn" type="submit">保存实际记录${v?'并验证':''}</button></form>
<details><summary>设置当前阻力与可用的下一档</summary><p class="hint">仅预设已具备、可规范使用的阻力或同一动作版本；组数不自动增加。修改档位会重新开始验证。</p><label class="field" for="currentLoad">当前档位 / 固定握持方式</label><input class="text-input" id="currentLoad" maxlength="100" value="${esc(e.load)}"><label class="field" for="nextLoad">下一档（未确定就留空）</label><input class="text-input" id="nextLoad" maxlength="100" placeholder="例如：已购中阻力带，握在标记 B" value="${esc(e.next?.label||'')}"><button class="btn secondary" id="saveConfig" type="button">保存档位设置</button></details><div id="recordResult" aria-live="polite"></div>`;
const makeInputs=()=>{const n=$('temporaryRecord').checked?Math.max(1,e.sets-1):e.sets;$('setInputs').innerHTML=Array.from({length:n},(_,i)=>`<label class="set-field">第 ${i+1} 组<input class="text-input" name="set${i}" type="number" inputmode="numeric" min="0" max="600" step="1" placeholder="${e.target[i]}" required></label>`).join('')};makeInputs();$('temporaryRecord').onchange=makeInputs;
if($('startValidation'))$('startValidation').onclick=()=>attempt(()=>{transact(s=>startValidation(s,id));openExercise(id)});
if($('cancelValidation'))$('cancelValidation').onclick=()=>attempt(()=>{transact(s=>s.exercises[id].validation=null);openExercise(id)});
if($('singleReduce'))$('singleReduce').onclick=()=>attempt(()=>{transact(s=>{const k=localDate()+':exercise:'+id;s.temporary[k]=!s.temporary[k]});render();openExercise(id)});
if($('resume'))$('resume').onclick=()=>attempt(()=>{if(!$('resumeCheck').checked)throw Error('请先确认目前适合恢复。');transact(s=>{s.exercises[id].blocked=false;s.exercises[id].validation=null;s.events.push({type:'resume',exercise:id,at:new Date().toISOString()})});render();openExercise(id)});
$('saveConfig').onclick=()=>attempt(()=>{transact(s=>configure(s,id,{load:$('currentLoad').value,next:$('nextLoad').value}));render();openExercise(id);notify('档位已保存；进阶验证重新计数。')});
$('recordForm').onsubmit=ev=>{ev.preventDefault();try{const data=new FormData(ev.target);const vals=[...$('setInputs').querySelectorAll('input')].map(x=>x.value===''?NaN:Number(x.value));const input={date:data.get('date'),values:vals,rir:data.get('rir'),quality:data.get('quality'),comparable:data.get('comparable'),temporary:$('temporaryRecord').checked};const r=transact(s=>record(s,id,input));$('recordResult').innerHTML=`<div class="success">${esc(r.outcome)}</div><button class="btn secondary" id="doneRecord">返回训练卡</button>`;$('doneRecord').onclick=()=>{$('exerciseDialog').close();render()};ev.target.querySelector('[type=submit]').disabled=true;$('formError').innerHTML='';$('recordResult').scrollIntoView({behavior:'smooth',block:'nearest'});render();}catch(e){$('formError').innerHTML=`<div class="error">${esc(e.message)}</div>`;}};
if(!$('exerciseDialog').open)$('exerciseDialog').showModal();}
function renderHistory(){const records=Object.values(state.exercises).flatMap(e=>e.records.map(r=>({e,r}))).sort((a,b)=>b.r.date.localeCompare(a.r.date)||b.r.logged.localeCompare(a.r.logged));const changes=Object.values(state.exercises).flatMap(e=>e.changes.map(c=>({e,c}))).sort((a,b)=>b.c.at.localeCompare(a.c.at));$('main').innerHTML=`<h1>训练记录</h1><div class="muted">没有记录的日子留白，不推定没有训练。</div><h3 style="margin-top:25px">调整历史</h3>${changes.length?changes.map(({e,c})=>`<div class="log"><div class="row"><strong>${esc(e.name)}</strong><span class="history-tag">${c.undone?'已撤销':'自动进阶'}</span></div><div class="tiny">${esc(c.date)}</div><div>${esc(c.before.load)} ${esc(c.before.target.join('/'))} → ${esc(c.after.load)} ${esc(c.after.target.join('/'))} ${e.unit}</div><div class="muted">${esc(c.reason)}</div>${!c.undone&&e.changes.filter(x=>!x.undone).at(-1)===c?`<button class="inline" data-undo="${e.id}:${c.id}">撤销这次调整，保留实际记录</button>`:''}</div>`).join(''):'<div class="empty">暂时没有自动调整。<br>达到条件后，变化会保存在这里。</div>'}<h3 style="margin-top:27px">实际训练 · ${records.length} 条</h3>${records.length?records.map(({e,r})=>`<div class="log"><div class="row"><strong>${esc(e.name)}</strong><span class="tiny">${esc(r.date)}</span></div><div>${e.sides?'每侧 ':''}${esc(r.values.join(' / '))} ${e.unit}${r.temporary?' · 临时减量':''}</div><div class="muted">${esc(r.outcome)}</div></div>`).join(''):'<div class="empty">先按当前计划训练。<br>需要时再记录一个动作。</div>'}`;document.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>attempt(()=>{const[id,cid]=b.dataset.undo.split(':');transact(s=>undo(s,id,cid));renderHistory();notify('已撤销计划调整；原训练记录保留。')}));}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function renderExport(){const[from,to]=weekRange();const count=Object.values(state.exercises).reduce((n,e)=>n+e.records.length,0);$('main').innerHTML=`<h1>设置</h1><div id="accountSlot"></div><div class="muted">已保存 ${count} 条实际训练记录。登录邮箱后自动同步；离线修改会在联网后补传。未登录的记录仅存此设备。</div><section class="card" id="pwaInstall"></section><section class="card"><h3>Obsidian 周报</h3><p class="muted">当前计划快照＋所选周实际记录＋自动调整及原因。导出的 Markdown 可手动放进知识库。</p><label class="field" for="exportDate">选择这一周中的任意一天</label><input class="text-input" type="date" id="exportDate" value="${localDate()}"><div class="hint" id="weekLabel">${from} — ${to}</div><button class="btn" id="exportMarkdown">导出 Markdown 周报</button><button class="btn secondary" id="copyMarkdown">复制周报文字</button></section><section class="card"><h3>完整备份与恢复</h3><p class="muted">JSON 包含所有记录、计划、验证进度和调整历史。换设备或清除浏览器数据前，先导出备份。</p><button class="btn secondary" id="exportBackup">下载完整备份</button><label class="btn secondary file-label">选择备份文件恢复<input type="file" id="importBackup" accept=".json,application/json"></label><div id="importPreview"></div></section><details><summary>记录、进阶与工具边界</summary><p>仅在你输入后运行预设规则。无新记录、余力不确定或条件不一致时，不自动加码。同一动作一天只能一条记录，避免重复计数；补录须按时间顺序。</p><p>普通重复动作验证两次后每组目标增加1次；保持类增加5秒，均不超过预设范围。两次均达次数上限，且已设置可用下一档时，自动换档并回到下限。轻下肢要求保留约4次余力。换档后重新校准。</p><p>当前版本仅做次数、保持时间和预设档位推进，不自动增加组数或训练天数。修改动作种类、组数或处理持续异常，应重新审视计划。</p><p>清除浏览器数据、更换设备或无痕模式可能导致记录丢失。周报用于阅读，完整备份用于恢复。工具不以训练数据预测体型，不上传身体照片。登录后训练记录与计划会保存到账号云端。</p></details>`;
mountInstallCard($('pwaInstall'));
$('exportDate').onchange=()=>{try{const[a,b]=weekRange($('exportDate').value);$('weekLabel').textContent=`${a} — ${b}`}catch{$('weekLabel').textContent='请选择有效日期'}};
$('exportMarkdown').onclick=()=>attempt(()=>{const d=$('exportDate').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(d))throw Error('请选择有效日期');const[a]=weekRange(d);download(`训练周报-${a}.md`,markdown(state,d),'text/markdown;charset=utf-8');notify('周报已生成，可放入 Obsidian。')});
$('copyMarkdown').onclick=async()=>{try{await navigator.clipboard.writeText(markdown(state,$('exportDate').value));notify('周报已复制。')}catch{notify('当前浏览器不能直接复制，请使用导出 Markdown。')}};
$('exportBackup').onclick=()=>download(`mantou-training-backup-${localDate()}.json`,JSON.stringify(state,null,2),'application/json');
$('importBackup').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('备份超过5MB，请检查文件。');pendingImport=validateBackup(JSON.parse(await file.text()));const n=Object.values(pendingImport.exercises).reduce((sum,e)=>sum+e.records.length,0);$('importPreview').innerHTML=`<div class="warning">备份包含 ${n} 条记录。登录时合并到账号，保留不同日期记录；有分歧时需要选择。未登录时替换本机数据。请先下载当前完整备份。</div><button class="btn warn" id="confirmImport">确认替换并恢复</button><button class="inline" id="cancelImport">取消</button>`;$('cancelImport').onclick=()=>{pendingImport=null;$('importPreview').innerHTML=''};$('confirmImport').onclick=()=>attempt(()=>{const restored=clone(pendingImport);if(!cloud?.import(restored))localStorage.setItem(KEY,JSON.stringify(restored));if(!cloud?.isAccount())state=restored;pendingImport=null;$('storageWarning').hidden=true;$('saveStatus').textContent='已恢复并保存';render();notify('备份已恢复。')});}catch(e){pendingImport=null;$('importPreview').innerHTML=`<div class="error">未恢复：${esc(e.message)}</div>`;}};}
function showSettings(){page='export';render();window.scrollTo(0,0);const panel=document.querySelector('.cloud-panel');if(panel)panel.open=true;}
$('accountShortcut').onclick=showSettings;$('systemStatus').onclick=showSettings;
let cloudMessage='未登录 · 记录保存在本机',pwaMessage='正在准备离线文件';function statusLine(){const error=/失败|冲突|不可|重新登录|另一|检查浏览器/.test(cloudMessage),pwaError=/未准备好|先联网/.test(pwaMessage);$('systemStatus').textContent=(/离线/.test(pwaMessage)&&!navigator.onLine?'离线 · ':/已与云端/.test(cloudMessage)?'已同步 · ':/未登录/.test(cloudMessage)?'本机记录 · ':/待同步|等待|正在同步/.test(cloudMessage)?'待同步 · ':'账号记录 · ')+(/已就绪|离线模式/.test(pwaMessage)?'可离线使用':'准备离线文件');$('systemStatus').title=cloudMessage+'；'+pwaMessage;$('systemAlert').hidden=!(error||pwaError);$('systemAlert').textContent=error?cloudMessage:pwaMessage;}window.addEventListener('training:cloud-status',e=>{cloudMessage=e.detail;statusLine()});window.addEventListener('training:pwa-status',e=>{pwaMessage=e.detail;statusLine()});
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0)});document.querySelector('.brand').onclick=e=>{e.preventDefault();page='plan';render();window.scrollTo(0,0)};$('closeDialog').onclick=()=>$('exerciseDialog').close();$('exerciseDialog').addEventListener('click',e=>{if(e.target===$('exerciseDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});render();

cloud=mountCloud({guest:()=>{try{return validateBackup(JSON.parse(localStorage.getItem(KEY)))}catch{return fresh()}},apply:(next,account)=>{state=validateBackup(next);$('saveStatus').textContent=account?'账号数据 · 本机缓存':'设备内保存';render();},notify});
